(function validateAssignments() {
  const assignees = Array.isArray(window.AUDIT_ASSIGNEES) ? window.AUDIT_ASSIGNEES : [];
  const assignments = Array.isArray(window.MEASUREMENT_ASSIGNMENTS) ? window.MEASUREMENT_ASSIGNMENTS : [];
  console.assert(assignees.length === 8, 'Должно быть 8 ролей');
  console.assert(assignments.length === 131, 'Должно быть 131 назначения');
  console.assert(Math.abs(assignments.reduce((s, a) => s + Number(a.timingMinutes || 0), 0) - 1512.1) < 0.01, 'Сумма нагрузки должна быть 1512.1 мин');
  const assigneeKeys = new Set(assignees.map(a => a.key));
  const assignmentIds = new Set();
  const operationIds = new Set((window.OPERATIONS || []).map(o => o.id));
  assignments.forEach(a => {
    console.assert(!assignmentIds.has(a.id), 'ID назначений должны быть уникальны: ' + a.id);
    assignmentIds.add(a.id);
    console.assert(operationIds.has(a.operationId), 'Не найдена DI-группа для назначения: ' + a.id + ' / ' + a.operationId);
    console.assert(['izhs_jd', 'gzh', 'ddu'].includes(a.creditGoalKey), 'Некорректная цель кредита: ' + a.id);
    console.assert(assigneeKeys.has(a.assigneeKey), 'Некорректный проверяющий: ' + a.id);
    console.assert(a.date && a.start && a.end, 'Пустая дата или время: ' + a.id);
    console.assert(a.start < a.end, 'Некорректное время назначения: ' + a.id);
  });
  assignees.forEach(assignee => {
    const rows = assignments.filter(a => a.assigneeKey === assignee.key);
    const minutes = Number(rows.reduce((s, a) => s + Number(a.timingMinutes || 0), 0).toFixed(2));
    console.assert(rows.length === assignee.assignmentsCount, 'Не совпало число назначений для ' + assignee.label);
    console.assert(Math.abs(minutes - Number(assignee.assignedMinutes || 0)) <= 0.05, 'Не совпали минуты назначений для ' + assignee.label);
  });
})();
